"""
Dial calculus: exact evaluation of the cost model, the exchangeable cap, the sharp
cap-breaking criterion, and the quantitative escape margin.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal, Optional

CAP: float = 4.0 / 3.0


@dataclass(frozen=True)
class DialReport:
    """Full classification of a dial with soundness s and retention theta."""
    soundness: float
    retention: float
    cost: float
    speedup: float
    exchangeable: bool
    beats_cap: bool
    criterion_value: float          # s * (1 - theta), compared against 1/4
    escape_margin: float            # (1 - 2 theta)^2 / (4 (1 - theta))
    soundness_excess: float         # s - theta, must exceed escape_margin if beats_cap
    regime: Literal["exchangeable", "sub-cap biased", "structural / super-cap"]


def dial_cost(s: float, theta: float, overhead: float = 0.0) -> float:
    """Expected cost, normalised so the unfiltered sweep costs 1.

    With overhead > 0 the dial is additionally charged `overhead` per candidate for its
    own evaluation, giving the loaded cost `overhead + 1 - s + s*theta`.
    """
    if not 0.0 <= s <= 1.0:
        raise ValueError("soundness must lie in [0, 1]")
    if not 0.0 < theta <= 1.0:
        raise ValueError("retention must lie in (0, 1]")
    return overhead + 1.0 - s + s * theta


def dial_speedup(s: float, theta: float, overhead: float = 0.0) -> float:
    """Speedup over the unfiltered sweep."""
    return 1.0 / dial_cost(s, theta, overhead)


def escape_margin(theta: float) -> float:
    """Soundness excess required to beat the 4/3 cap: (1-2 theta)^2 / (4 (1 - theta))."""
    if theta >= 1.0:
        return float("inf")
    return (1.0 - 2.0 * theta) ** 2 / (4.0 * (1.0 - theta))


def exchangeable_cap(overhead: float = 0.0) -> float:
    """The best speedup attainable by an exchangeable dial: 1 / (overhead + 3/4)."""
    return 1.0 / (overhead + 0.75)


def classify_dial(s: float, theta: float, overhead: float = 0.0,
                  tol: float = 1e-12) -> DialReport:
    """Evaluate and classify a dial in one pass.  O(1) time and space."""
    cost = dial_cost(s, theta, overhead)
    speed = 1.0 / cost
    crit = s * (1.0 - theta)
    exch = abs(s - theta) <= tol
    if overhead == 0.0:
        beats = crit > 0.25 + tol
    else:
        beats = speed > exchangeable_cap(overhead) + tol
    if exch:
        regime = "exchangeable"
    elif beats:
        regime = "structural / super-cap"
    else:
        regime = "sub-cap biased"
    return DialReport(
        soundness=s,
        retention=theta,
        cost=cost,
        speedup=speed,
        exchangeable=exch,
        beats_cap=beats,
        criterion_value=crit,
        escape_margin=escape_margin(theta),
        soundness_excess=s - theta,
        regime=regime,  # type: ignore[arg-type]
    )


def minimum_soundness_to_beat_cap(theta: float) -> Optional[float]:
    """Least soundness beating 4/3 at the given retention, or None if unattainable."""
    if theta >= 0.75:
        return None
    s = 0.25 / (1.0 - theta)
    return s if s < 1.0 else None


if __name__ == "__main__":
    for s_val, theta_val in ((0.5, 0.5), (1.0, 0.5), (1.0, 0.25), (0.9, 0.1), (0.3, 0.3)):
        r = classify_dial(s_val, theta_val)
        print(f"s={r.soundness:4.2f} theta={r.retention:4.2f} "
              f"speedup={r.speedup:6.4f} regime={r.regime}")
    print("\nminimum soundness to beat the cap:")
    for theta_val in (0.1, 0.25, 0.5, 0.7, 0.8):
        print(f"  theta={theta_val:4.2f} -> {minimum_soundness_to_beat_cap(theta_val)}")

"""
Berggren orbit enumeration and revealed-residue-table extraction.

Breadth-first enumeration of the ternary tree of primitive Pythagorean triples rooted at
(3,4,5), with online extraction of the residue table revealed modulo a given m, and
detection of the depth at which that table saturates (stops growing).
"""

from __future__ import annotations

from typing import Dict, Iterator, List, Set, Tuple

Triple = Tuple[int, int, int]


def b1(t: Triple) -> Triple:
    a, b, c = t
    return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)


def b2(t: Triple) -> Triple:
    a, b, c = t
    return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)


def b3(t: Triple) -> Triple:
    a, b, c = t
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


def is_pythagorean(t: Triple) -> bool:
    a, b, c = t
    return a * a + b * b == c * c


def berggren_bfs(max_depth: int, root: Triple = (3, 4, 5)) -> Iterator[Tuple[int, Triple]]:
    """Yield (depth, triple) for every node down to max_depth, breadth-first.

    The tree is ternary, so depth d contributes 3**d nodes and the enumeration to depth
    D costs Theta((3**(D+1) - 1)/2) node expansions with O(3**D) memory for the frontier.
    """
    frontier: List[Triple] = [root]
    yield (0, root)
    for depth in range(1, max_depth + 1):
        nxt: List[Triple] = []
        for t in frontier:
            for child in (b1(t), b2(t), b3(t)):
                nxt.append(child)
                yield (depth, child)
        frontier = nxt


def revealed_table(max_depth: int, modulus: int) -> Dict[int, Set[Triple]]:
    """Cumulative revealed residue table modulo `modulus`, indexed by depth."""
    table: Dict[int, Set[Triple]] = {}
    seen: Set[Triple] = set()
    for depth, t in berggren_bfs(max_depth):
        a, b, c = t
        seen.add((a % modulus, b % modulus, c % modulus))
        table[depth] = set(seen)
    return table


def saturation_depth(max_depth: int, modulus: int) -> int:
    """Least depth at which the cumulative revealed table stops growing (or max_depth)."""
    table = revealed_table(max_depth, modulus)
    sizes = [len(table[d]) for d in sorted(table)]
    final = sizes[-1]
    for d, size in enumerate(sizes):
        if size == final:
            return d
    return max_depth


def verify_invariants(max_depth: int) -> Dict[str, bool]:
    """Check the congruence invariant and the leg-divisible-by-3 congruence."""
    ok_pyth, ok_cong, ok_three = True, True, True
    for _, (a, b, c) in berggren_bfs(max_depth):
        ok_pyth &= is_pythagorean((a, b, c))
        ok_cong &= (a % 2 == 1 and b % 4 == 0 and c % 4 == 1)
        ok_three &= ((a * b) % 3 == 0)
    return {"pythagorean": ok_pyth, "a odd, 4|b, c=1 mod 4": ok_cong, "3 | a*b": ok_three}


if __name__ == "__main__":
    print("invariants:", verify_invariants(6))
    for m in (3, 4, 5, 7, 8, 16):
        tbl = revealed_table(6, m)
        print(f"  modulus {m:2d}: |revealed| by depth = "
              f"{[len(tbl[d]) for d in sorted(tbl)]}, saturates at depth "
              f"{saturation_depth(6, m)}")
    print("\n  mod 4 table:", sorted(revealed_table(6, 4)[6]))
